<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class CardToCardPayment {
 public static function register(): void { add_shortcode('avanik_card_to_card',[self::class,'render']); add_action('admin_post_avanik_card_receipt',[self::class,'save']); }
 public static function render(): string { if(!is_user_logged_in())return '<p>ابتدا وارد شوید.</p>'; $id=(int)($_GET['payment_id']??0); global $wpdb; $p=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.PaymentRepository::table_name().' WHERE payment_id=%d AND customer_id=%d',$id,get_current_user_id()),ARRAY_A); if(!$p||$p['gateway']!=='card_to_card')return '<p>پرداخت پیدا نشد.</p>'; ob_start(); ?><section dir="rtl"><h2>پرداخت کارت به کارت</h2><p>مبلغ: <?php echo esc_html(number_format((float)$p['amount']).' '.$p['currency']); ?></p><p>پس از انتقال وجه، تصویر رسید را ارسال کنید.</p><form method="post" enctype="multipart/form-data" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('avanik_card_receipt'); ?><input type="hidden" name="action" value="avanik_card_receipt"><input type="hidden" name="payment_id" value="<?php echo esc_attr($id); ?>"><input required type="file" name="receipt" accept="image/*,.pdf"><button type="submit">ارسال رسید</button></form></section><?php return (string)ob_get_clean(); }
 public static function save(): void { if(!is_user_logged_in()||!check_admin_referer('avanik_card_receipt'))wp_die('Unauthorized'); global $wpdb; $id=(int)($_POST['payment_id']??0); $p=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.PaymentRepository::table_name().' WHERE payment_id=%d AND customer_id=%d',$id,get_current_user_id()),ARRAY_A); if(!$p||$p['gateway']!=='card_to_card')wp_die('Payment not found'); if(empty($_FILES['receipt']['name']))wp_die('Receipt required'); require_once ABSPATH.'wp-admin/includes/file.php'; $up=wp_handle_upload($_FILES['receipt'],['test_form'=>false,'mimes'=>['jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','pdf'=>'application/pdf']]); if(isset($up['error']))wp_die(esc_html($up['error'])); $wpdb->update(PaymentRepository::table_name(),['status'=>'pending_verification','metadata'=>wp_json_encode(['receipt_url'=>$up['url']]),'updated_at'=>current_time('mysql')],['payment_id'=>$id,'customer_id'=>get_current_user_id()]); wp_safe_redirect(home_url('/payment/?payment_id='.$id)); exit; }
}